  "foot": "<footer class=\"foot\">\n  <p class=\"round-note\" data-ink=\"\">TEU figures are rounded up to whole TEU. Totals come from the exact values, so rows may not add up exactly.</p>\n  <p data-ink=\"\" id=\"foot-source\">Figures in TEU. Data from the backend at http://127.0.0.1:8001.</p>\n  <p data-ink=\"\">MGH · Carrier Allocation &amp; Utilization</p>\n</footer>"
